True def transform(grid):
    n=len(grid); w=len(grid[0])
    marks=[(i,row[0]) for i,row in enumerate(grid) if any(row)]
    if not marks: return [r[:] for r in grid]
    colors=[]
    for _,c in marks:
        if c not in colors: colors.append(c)
    period=len(colors)
    # Assign colors to phases using the observed band rows.
    phases={}
    a,base=marks[0]
    for i,c in marks:
        phases[(i-a)%period]=c
    # Any unobserved phase is filled in first-seen color order.
    remaining=[c for c in colors if c not in phases.values()]
    for k in range(period):
        if k not in phases: phases[k]=remaining.pop(0)
    out=[]
    for i,row in enumerate(grid):
        c=row[0] if any(row) else phases[(i-a)%period]
        out.append(row[:] if any(row) else [c]*w)
    return out
